import{_ as d,C as o,o as t,c as r,a2 as a,b as i,w as s,a as p,E as l,a3 as c}from"./chunks/framework.D6RJXrbK.js";const v=JSON.parse('{"title":"第 1 章 授权的几种形态：从 ACL 到 ReBAC","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/01-authz-models.md","filePath":"chapters/01-authz-models.md","lastUpdated":1791513046000}'),h={name:"chapters/01-authz-models.md"};function u(b,e,g,m,A,C){const n=o("Mermaid");return t(),r("div",null,[e[1]||(e[1]=a(`<h1 id="第-1-章-授权的几种形态-从-acl-到-rebac" tabindex="-1">第 1 章 授权的几种形态：从 ACL 到 ReBAC <a class="header-anchor" href="#第-1-章-授权的几种形态-从-acl-到-rebac" aria-label="Permalink to &quot;第 1 章 授权的几种形态：从 ACL 到 ReBAC&quot;">​</a></h1><blockquote><p>本章目标：用同一个“云盘”场景，比较 ACL、RBAC、ABAC、ReBAC 四种授权方式；理解 Zanzibar 的三个核心概念（关系元组、用户集重写、一致性）；把它们对应到 OpenFGA 的 API 上。 前置：无。对应代码：无（从第 4 章开始写代码）。</p></blockquote><h2 id="_1-1-一个贯穿全书的场景" tabindex="-1">1.1 一个贯穿全书的场景 <a class="header-anchor" href="#_1-1-一个贯穿全书的场景" aria-label="Permalink to &quot;1.1 一个贯穿全书的场景&quot;">​</a></h2><p>设想一个类似 Google Drive 的云盘：</p><ul><li>用户可以<strong>拥有</strong>文档，也可以把文档<strong>分享</strong>给别的用户；</li><li>文档放在<strong>文件夹</strong>里，文件夹可以嵌套，<strong>能看文件夹就能看里面的所有文档</strong>；</li><li>公司有<strong>团队</strong>，团队可以包含子团队，可以把文件夹分享给整个团队；</li><li>某些文档可以<strong>公开</strong>给所有人；</li><li>管理员可以<strong>拉黑</strong>某个人，被拉黑的人即使在团队里也不能看这份文档；</li><li>外包人员的权限<strong>只在合同期内有效</strong>。</li></ul><p>系统要回答三类问题：</p><table tabindex="0"><thead><tr><th>问题</th><th>名字</th></tr></thead><tbody><tr><td>anne 能看 design.doc 吗？</td><td>Check</td></tr><tr><td>anne 能看哪些文档？</td><td>ListObjects</td></tr><tr><td>谁能看 design.doc？</td><td>ListUsers</td></tr></tbody></table><p>下面用四种方式来回答。</p><h2 id="_1-2-acl-把名单挂在资源上" tabindex="-1">1.2 ACL：把名单挂在资源上 <a class="header-anchor" href="#_1-2-acl-把名单挂在资源上" aria-label="Permalink to &quot;1.2 ACL：把名单挂在资源上&quot;">​</a></h2><p>访问控制列表（Access Control List）为每个资源存一张“谁能做什么”的表：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>design.doc:  anne=owner, bob=viewer, carol=viewer</span></span>
<span class="line"><span>budget.xls:  bob=owner</span></span></code></pre></div><p>Check 只要查一次表，非常快，也很直观。问题在于<strong>所有的继承关系都要展开成名单</strong>：把文件夹分享给团队时，要把团队的每个成员写到文件夹里每份文档的 ACL 上；有人入职、离职或换团队，要回头改成千上万条 ACL。这种“写放大”在名单变动频繁时无法维护。</p><h2 id="_1-3-rbac-在用户和权限之间加一层角色" tabindex="-1">1.3 RBAC：在用户和权限之间加一层角色 <a class="header-anchor" href="#_1-3-rbac-在用户和权限之间加一层角色" aria-label="Permalink to &quot;1.3 RBAC：在用户和权限之间加一层角色&quot;">​</a></h2><p>基于角色的访问控制（Role-Based Access Control）先把权限归到角色上，再把角色分给用户：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>role editor:  document.read, document.write</span></span>
<span class="line"><span>role viewer:  document.read</span></span>
<span class="line"><span>anne -&gt; editor, bob -&gt; viewer</span></span></code></pre></div><p>角色解决了“权限组合”的复用问题，适合“财务可以看所有报表”这种<strong>全局</strong>规则。但云盘的规则是<strong>按资源</strong>的：anne 是 design.doc 的编辑者，却只是 budget.xls 的读者。要用 RBAC 表达，只能为每份文档造一组角色（<code>design.doc-editor</code>、<code>design.doc-viewer</code>……），这就是常说的“角色爆炸”。而且“文件夹的读者能读里面的文档”这样的<strong>层级</strong>关系，角色本身表达不了。</p><h2 id="_1-4-abac-用属性写规则" tabindex="-1">1.4 ABAC：用属性写规则 <a class="header-anchor" href="#_1-4-abac-用属性写规则" aria-label="Permalink to &quot;1.4 ABAC：用属性写规则&quot;">​</a></h2><p>基于属性的访问控制（Attribute-Based Access Control）用一个策略引擎（例如 OPA/Rego、AWS IAM、Cedar）对“主体属性 + 资源属性 + 环境属性”求值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>allow if resource.owner == user.id</span></span>
<span class="line"><span>allow if user.department == resource.department and time &lt; resource.expires_at</span></span></code></pre></div><p>ABAC 很适合表达“合同期内有效”“只能在公司网络访问”这样的<strong>上下文条件</strong>。它的弱点在于：</p><ul><li>规则需要的属性得在请求时带上，比如“这份文档所在的文件夹链”“用户所在的所有团队”。属性本身就是一张关系图，策略引擎不负责存它，调用方要自己去查；</li><li><strong>反向查询很难</strong>：“anne 能看哪些文档”需要对每份文档都求值一遍规则。</li></ul><h2 id="_1-5-rebac-把授权看成一张关系图" tabindex="-1">1.5 ReBAC：把授权看成一张关系图 <a class="header-anchor" href="#_1-5-rebac-把授权看成一张关系图" aria-label="Permalink to &quot;1.5 ReBAC：把授权看成一张关系图&quot;">​</a></h2><p>基于关系的访问控制（Relationship-Based Access Control）直接把“谁和什么有什么关系”作为数据存下来，每条数据是一个<strong>关系元组</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>document:design#owner@user:anne          anne 是 design 的 owner</span></span>
<span class="line"><span>document:design#parent@folder:eng        design 在 eng 文件夹里</span></span>
<span class="line"><span>folder:eng#viewer@team:platform#member   platform 团队的成员都是 eng 文件夹的 viewer</span></span>
<span class="line"><span>team:platform#member@user:bob            bob 是 platform 团队的成员</span></span></code></pre></div><p>格式是 <code>object#relation@user</code>，读作“<strong>user 是 object 的 relation</strong>”。注意第三条的 user 不是一个人，而是 <code>team:platform#member</code>，意思是“platform 团队的所有成员”。这种“某对象上某关系的所有主体”叫作 <strong>userset</strong>（用户集），它让一条元组可以代表一群人。</p><p>元组只是数据。“文件夹的 viewer 也是文档的 viewer”这样的规则，写在<strong>授权模型</strong>里：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type document</span></span>
<span class="line"><span>  relations</span></span>
<span class="line"><span>    define parent: [folder]</span></span>
<span class="line"><span>    define owner: [user]</span></span>
<span class="line"><span>    define viewer: [user, team#member] or owner or viewer from parent</span></span></code></pre></div><ul><li><code>[user, team#member]</code>：可以直接写元组赋予这个关系，user 可以是一个用户，也可以是团队成员这个 userset；</li><li><code>or owner</code>：document 的 owner 也是 viewer；</li><li><code>viewer from parent</code>：沿着 <code>parent</code> 关系找到文件夹，文件夹的 viewer 也是这份文档的 viewer。</li></ul><p>于是“bob 能看 design 吗？”变成了一次<strong>图遍历</strong>：</p>`,29)),(t(),i(c,null,{default:s(()=>[l(n,{id:"mermaid-166",class:"mermaid",graph:"flowchart%20LR%0A%20%20D%5B%22document%3Adesign%23viewer%22%5D%20--%3E%7Cviewer%20from%20parent%7C%20F%5B%22folder%3Aeng%23viewer%22%5D%0A%20%20F%20--%3E%7C%22%5Bteam%23member%5D%22%7C%20T%5B%22team%3Aplatform%23member%22%5D%0A%20%20T%20--%3E%7C%22%5Buser%5D%22%7C%20B((%22user%3Abob%22))%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>ReBAC 天然支持按资源的权限、层级继承和团队嵌套，写放大也小：bob 换团队只需要改一条元组。反向查询也有了思路：从 bob 出发<strong>反着走</strong>这张图（第 18 章）。</p><p>ReBAC 的代价是：一次 Check 可能要读很多次存储，正确而高效地遍历这张图并不简单，这正是本书 Part III 到 Part VIII 要处理的问题。</p><h2 id="_1-6-四种方式放在一起" tabindex="-1">1.6 四种方式放在一起 <a class="header-anchor" href="#_1-6-四种方式放在一起" aria-label="Permalink to &quot;1.6 四种方式放在一起&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>ACL</th><th>RBAC</th><th>ABAC</th><th>ReBAC</th></tr></thead><tbody><tr><td>按资源授权</td><td>✓</td><td>角色爆炸</td><td>✓（靠属性）</td><td>✓</td></tr><tr><td>层级继承（文件夹 → 文档）</td><td>展开名单</td><td>✗</td><td>调用方给出层级</td><td>✓ <code>X from parent</code></td></tr><tr><td>团队嵌套</td><td>展开名单</td><td>角色继承</td><td>调用方给出</td><td>✓ userset</td></tr><tr><td>上下文条件（时间、IP）</td><td>✗</td><td>✗</td><td>✓</td><td>OpenFGA 用 <strong>条件</strong>（CEL）补上</td></tr><tr><td>“我能看哪些”</td><td>扫描所有 ACL</td><td>好做</td><td>难</td><td>✓ 反向展开</td></tr><tr><td>变更成本</td><td>高</td><td>中</td><td>低（规则）/ 取决于属性来源</td><td>低（改一条元组）</td></tr></tbody></table><p>它们并不互斥。RBAC 在 ReBAC 里只是一种特殊的模型：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type role</span></span>
<span class="line"><span>  relations</span></span>
<span class="line"><span>    define assignee: [user]</span></span>
<span class="line"><span>type report</span></span>
<span class="line"><span>  relations</span></span>
<span class="line"><span>    define viewer: [role#assignee]</span></span></code></pre></div><p>ABAC 则由 OpenFGA 的<strong>条件元组</strong>补上：元组上挂一个 CEL 表达式，Check 时用请求带来的上下文求值（第 14 章）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>define viewer: [user with non_expired]</span></span>
<span class="line"><span>condition non_expired(current_time: timestamp, expires_at: timestamp) {</span></span>
<span class="line"><span>  current_time &lt; expires_at</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_1-7-zanzibar-的三个关键设计" tabindex="-1">1.7 Zanzibar 的三个关键设计 <a class="header-anchor" href="#_1-7-zanzibar-的三个关键设计" aria-label="Permalink to &quot;1.7 Zanzibar 的三个关键设计&quot;">​</a></h2><p>Zanzibar 是 Google 内部为 Drive、YouTube、Cloud 等几百个服务提供授权的系统，论文描述了它的设计。OpenFGA 继承了其中三点。</p><p><strong>1. 关系元组是唯一的数据形式。</strong> 所有服务都用同一种格式 <code>object#relation@user</code> 存储授权数据，<code>user</code> 可以是一个用户，也可以是一个 userset。这让一个授权服务就能服务所有业务。</p><p><strong>2. 用重写规则描述关系如何推导（userset rewrite）。</strong> 论文里每个 namespace（相当于 OpenFGA 的 type）为每个关系配置一个重写规则，规则由几个原语组合而成：</p><table tabindex="0"><thead><tr><th>Zanzibar 原语</th><th>含义</th><th>OpenFGA DSL</th><th>OpenFGA 的 protobuf 类型</th></tr></thead><tbody><tr><td><code>_this</code></td><td>直接写在这个关系上的元组</td><td><code>[user, team#member]</code></td><td><code>Userset_This</code></td></tr><tr><td><code>computed_userset</code></td><td>同一对象上的另一个关系</td><td><code>owner</code></td><td><code>Userset_ComputedUserset</code></td></tr><tr><td><code>tuple_to_userset</code></td><td>沿某个关系找到另一个对象，取它的某个关系</td><td><code>viewer from parent</code></td><td><code>Userset_TupleToUserset</code></td></tr><tr><td>union / intersection / exclusion</td><td>集合运算</td><td><code>or</code> / <code>and</code> / <code>but not</code></td><td><code>Userset_Union</code> / <code>Userset_Intersection</code> / <code>Userset_Difference</code></td></tr></tbody></table><p>这 6 种节点的定义在 <code>openfga/api</code> 模块的 <code>openfga/v1/authzmodel.pb.go:761</code>（<code>Userset</code>）到 <code>:882</code>（<code>Userset_Difference</code>）。全书的 Check 引擎、反向查询、带权图，本质上都是在这 6 种节点上做递归。</p><p><strong>3. 一致性：避免“新敌人”问题。</strong> 论文举的例子：Alice 把 Bob 从文件夹的权限里移除，然后往文件夹里放了一份新文档。如果授权服务用的是旧数据，Bob 仍然可以看到新文档。Zanzibar 用 <em>zookie</em>（一个时间戳令牌）让客户端要求“至少和某次写入一样新”的读取。OpenFGA 简化成了一个请求参数 <code>consistency</code>：默认 <code>MINIMIZE_LATENCY</code>，允许使用缓存；<code>HIGHER_CONSISTENCY</code> 绕过缓存，直接读存储（第 23 章）。</p><p>论文里还有两个大规模部署才需要的设计：分布式的 Spanner 存储，以及为深度嵌套的组预先计算成员关系的 Leopard 索引。OpenFGA 没有实现 Leopard，而是通过带权图选择更快的求值策略（第 27 章）。</p><h2 id="_1-8-openfga-的概念对照" tabindex="-1">1.8 OpenFGA 的概念对照 <a class="header-anchor" href="#_1-8-openfga-的概念对照" aria-label="Permalink to &quot;1.8 OpenFGA 的概念对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>是什么</th><th>本书章节</th></tr></thead><tbody><tr><td>Store</td><td>一个隔离的命名空间：一组模型 + 一组元组，常用来区分租户或环境</td><td>22</td></tr><tr><td>Authorization Model</td><td>用 DSL 写的类型和关系定义，<strong>不可修改</strong>，每次写入产生一个新版本（ID 是 ULID）</td><td>4、5、22</td></tr><tr><td>Relationship Tuple</td><td><code>object#relation@user</code>，可以带条件</td><td>6</td></tr><tr><td>Check</td><td>user 对 object 有 relation 吗</td><td>3、8–13</td></tr><tr><td>ListObjects / ListUsers</td><td>反向查询</td><td>18–20</td></tr><tr><td>Expand</td><td>把某个关系展开一层，给人看</td><td>16</td></tr><tr><td>Contextual Tuples</td><td>只在本次请求中生效、不落库的元组</td><td>13</td></tr><tr><td>Condition</td><td>元组上的 CEL 表达式</td><td>14</td></tr><tr><td>Assertions</td><td>和模型绑定的测试用例</td><td>23</td></tr><tr><td>ReadChanges</td><td>元组变更日志，可以用来同步数据，也用来让缓存失效</td><td>23</td></tr></tbody></table><h2 id="_1-9-小结" tabindex="-1">1.9 小结 <a class="header-anchor" href="#_1-9-小结" aria-label="Permalink to &quot;1.9 小结&quot;">​</a></h2><ul><li>ACL 简单但写放大，RBAC 表达不了按资源的层级，ABAC 擅长上下文但不擅长关系和反向查询；</li><li>ReBAC 把授权数据变成一张关系图，规则写在模型里，查询就是在图上遍历；</li><li>Zanzibar 给了三样东西：统一的元组、6 种重写原语、一致性令牌。OpenFGA 照搬了前两样，把第三样简化成 <code>consistency</code> 参数，又用条件补上了 ABAC 的能力。</li></ul><h2 id="_1-10-练习" tabindex="-1">1.10 练习 <a class="header-anchor" href="#_1-10-练习" aria-label="Permalink to &quot;1.10 练习&quot;">​</a></h2><ol><li>（巩固）用 <code>object#relation@user</code> 写出 1.1 节场景中“platform 团队包含 infra 子团队”的元组，并说明模型中 <code>team#member</code> 应该怎样定义才能让嵌套生效。</li><li>（扩展）用 RBAC 的方式在 OpenFGA 中建模“系统管理员可以看所有文档”：需要哪些类型和关系？为什么不能写 <code>document:*</code>？（提示：第 6 章会讲到，通配符只能出现在 user 一侧。）</li><li>（读源码）打开 <code>openfga/api</code> 模块的 <code>authzmodel.pb.go</code>，找到 <code>TupleToUserset</code> 结构体，它有哪两个字段？分别对应 DSL <code>viewer from parent</code> 里的哪个词？</li></ol><h2 id="_1-11-延伸阅读" tabindex="-1">1.11 延伸阅读 <a class="header-anchor" href="#_1-11-延伸阅读" aria-label="Permalink to &quot;1.11 延伸阅读&quot;">​</a></h2><ul><li>Zanzibar 论文第 2 节（模型）和第 3 节（一致性）</li><li>OpenFGA 文档 <em>Concepts</em> 一节：<a href="https://openfga.dev/docs/concepts" target="_blank" rel="noreferrer">https://openfga.dev/docs/concepts</a></li><li>OpenFGA 文档 <em>Modeling Guides</em>：常见模式（角色、组织、层级、黑名单、条件）的建模方法</li></ul>`,24))])}const f=d(h,[["render",u]]);export{v as __pageData,f as default};
